// decodeResponse applies the header-aware decode contract every GatherDeal
// client shares, decode(status, headers, body):
//
//  1. Content-Type is parsed structurally (case-insensitive type/subtype,
//     parameters such as charset ignored).
//  2. 2xx + application/problem+json is a [*ProtocolError]; any other 2xx
//     must be an application/json success envelope ({"status":"success"}),
//     decoded into out (an empty body is accepted when out is nil).
//  3. Non-2xx + application/problem+json is decoded into a [*Problem];
//     malformed JSON, a missing code, or a status different from the status
//     line is a [*ProtocolError].
//  4. Non-2xx + anything else is a [*StatusError].
func decodeResponse(status int, header http.Header, data []byte, out any) error {
	correlationID := header.Get(CorrelationHeader)
	fail := func(reason string, err error) error {
		return &ProtocolError{
			HTTPStatus:    status,
			CorrelationID: correlationID,
			Reason:        reason,
			Err:           err,
		}
	}
	media := mediaType(header.Get("Content-Type"))
	if status >= http.StatusOK && status < http.StatusMultipleChoices {
		switch {
		case media == ProblemMediaType:
			return fail("problem document with a success status", nil)
		case len(data) > MaxResponseBytes:
			return fail("response body exceeds MaxResponseBytes", nil)
		case len(data) == 0 && out == nil:
			return nil
		case media != "application/json":
			return fail("success response is not application/json", nil)
		}
		var env struct {
			Status string `json:"status"`
		}
		if err := json.Unmarshal(data, &env); err != nil {
			return fail("malformed success envelope", err)
		}
		if env.Status != "success" {
			return fail("2xx response is not a success envelope", nil)
		}
		if out == nil {
			return nil
		}
		if err := json.Unmarshal(data, out); err != nil {
			return fail("decode success payload", err)
		}
		return nil
	}
	if media != ProblemMediaType {
		return &StatusError{
			HTTPStatus:    status,
			CorrelationID: correlationID,
		}
	}
	if len(data) > MaxResponseBytes {
		return fail("response body exceeds MaxResponseBytes", nil)
	}
	var p Problem
	if err := json.Unmarshal(data, &p); err != nil {
		return fail("malformed problem document", err)
	}
	if p.Code == "" {
		return fail("problem document without a code", nil)
	}
	if p.Status != status {
		return fail("problem status differs from the status line", nil)
	}
	if p.Record != nil && p.Record.Kind == "" {
		p.Record = nil
	}
	if p.CorrelationID == "" {
		p.CorrelationID = correlationID
	}
	p.ContentLanguage = header.Get("Content-Language")
	return &p
}

