// ShouldRetry applies the one problem-aware retry policy every GatherDeal
// client shares:
//
//	| Response                                   | Retry?                                   | Delay                          |
//	| network error or timeout (no response)     | idempotent only                          | backoff 200 ms × 2ⁿ, jittered   |
//	| 502, 503, 504 without a problem document   | idempotent only                          | backoff                        |
//	| problem with retryable:true (429, 503)     | idempotent only; 429 also non-idempotent | max(retry_after_ms, backoff)   |
//	| any other problem (incl. 500), protocol    | never                                    | —                              |
//
// Idempotent methods are GET, HEAD, PUT, DELETE and OPTIONS (or any keyed
// request). Limits: RetryMaxAttempts attempts, RetryBudget per call, delays
// capped at RetryMaxDelay. It returns whether to retry and the delay.
func ShouldRetry(in RetryInput) (bool, time.Duration) {
	if in.Err == nil || in.Attempt >= RetryMaxAttempts {
		return false, 0
	}
	idempotent := in.Keyed || isIdempotentMethod(in.Method)
	delay := retryJitter(RetryBaseDelay << max(in.Attempt-1, 0))
	var retry bool
	var statusErr *StatusError
	var protocolErr *ProtocolError
	switch problem, isProblem := asProblem(in.Err); {
	case errors.As(in.Err, &protocolErr):
		return false, 0
	case errors.As(in.Err, &statusErr):
		switch statusErr.HTTPStatus {
		case http.StatusBadGateway, http.StatusServiceUnavailable, http.StatusGatewayTimeout:
			retry = idempotent
		}
	case isProblem:
		if !problem.Retryable {
			return false, 0
		}
		retry = idempotent || problem.Status == http.StatusTooManyRequests
		if hint := time.Duration(problem.RetryAfterMS) * time.Millisecond; hint > delay {
			delay = hint
		}
	default:
		// A transport error before any response.
		retry = idempotent
	}
	if !retry {
		return false, 0
	}
	delay = min(delay, RetryMaxDelay)
	if in.Elapsed+delay > RetryBudget {
		return false, 0
	}
	return true, delay
}

func isIdempotentMethod(method string) bool {
	switch method {
	case http.MethodGet, http.MethodHead, http.MethodPut, http.MethodDelete, http.MethodOptions:
		return true
	}
	return false
}

// retryJitter returns d/2 + rand[0, d/2).
func retryJitter(d time.Duration) time.Duration {
	half := d / 2
	if half <= 0 {
		return d
	}
	return half + rand.N(half)
}

